				FHitResult Empty(FVector::ZeroVector, FVector(100.0, 0.0, 0.0));
				UPrimitiveComponent EmptyComponent = Empty.GetComponent();
				AActor ActorCdo = TSubclassOf<AActor>(AActor::StaticClass()).GetDefaultObject();
